type auditedPayments struct {
    PaymentService              // embedded: forwards every method not overridden
    sink AuditSink
}

func (a auditedPayments) Pay(ctx context.Context, p Payment) (Receipt, error) {
    actor := SubjectFrom(ctx)
    a.sink.Record(actor, "pay", p.ID, "attempt")
    r, err := a.PaymentService.Pay(ctx, p)
    a.sink.Record(actor, "pay", p.ID, outcomeOf(err))
    return r, err
}
